/**
 * dsh-verify public contract (the single source of truth on the type side).
 *
 * If this file and any prose description ever disagree, this file wins -
 * update the prose, not the types.
 *
 * This package has **no runtime code** (only .d.ts, erased at compile time),
 * so it can only be used with `import type`. Any runtime value import such as
 * `import { TOOL_PREFIX } from '@alexzeng666/dsh-verify-contract'` will fail to load.
 */

/** Who produced a fragment. `orchestrator` belongs to the dsh-verify layer only; sub-packages must not use it. */
export type FragmentSource = 'quota' | 'crashlab' | 'probe' | 'timelab' | 'orchestrator';

/**
 * One report fragment, produced by any package in the suite.
 *
 * - `result: 'fail'` means the thing under test did not meet expectations (the conclusion is trustworthy)
 * - `result: 'error'` means the verifier itself could not run (the conclusion is not trustworthy)
 *
 * Both count as "not passing", but the report text must keep them distinct.
 */
export interface VerifyFragment {
  source: FragmentSource;
  /** Generated by the producer: quota=VQ- / crashlab=VC- / probe=VP- / timelab=VT- / orchestrator=V- */
  verify_id: string;
  result: 'pass' | 'fail' | 'error';
  /** One line, human readable, never empty. */
  summary: string;
  /** Free-form area owned by each package; consumers pass it through and never parse it. Use {} when empty. */
  detail: Record<string, unknown>;
  /** Evidence pointers: absolute paths or URIs that actually exist; use [] when there is none. */
  evidence: string[];
  /** Time spent by this verification itself, in milliseconds - not the duration of the command under test. */
  elapsed_ms: number;
}

/** Cross-package correlation event; written to `<workspace>/.verify/timeline.jsonl`, one JSON per line. */
export interface TimelineEntry {
  /** Epoch milliseconds, always real wall clock (never the virtual time shifted by timelab). */
  ts: number;
  source: FragmentSource;
  /** Reserved values: started / exited / killed / crashed / attached / detached / shifted. Others are free-form. */
  event: string;
  pid?: number;
  detail?: Record<string, unknown>;
}

/** Documentation and naming check only; tool names are hardcoded literals, never assembled at runtime. */
export declare const TOOL_PREFIX: 'verify_';
